#!/bin/sh
# 用 nm 读符号表：区分 T/U/d/b/t 符号类型
# 期望输出见 expected_output（本机 MinGW 工具链真实执行捕获）

cat > util.c << 'EOF'
#include <stdio.h>

int ext_init = 5;              /* D：已初始化的全局变量（外部链接） */
static int call_count;         /* b：static 未初始化（内部链接，.bss） */
static int helper(void)        /* t：static 函数（内部链接） */
{
    return ++call_count;
}

int add(int a, int b)          /* T：外部函数（外部链接） */
{
    return a + b + helper();
}

void show(void)
{
    printf("ext=%d count=%d\n", ext_init, call_count);   /* 引出 U printf */
}
EOF

gcc -c util.c -o util.o
nm util.o      # 大写=外部链接，小写=内部链接（static）；U=未定义待链接
nm -S util.o   # 附加符号大小
